 32	package com.pousadamareaalta;
 33	
 34	import com.zaxxer.hikari.HikariConfig;
 35	import com.zaxxer.hikari.HikariDataSource;
 36	
 37	import java.sql.Connection;
 38	import java.sql.Statement;
 39	
 40	public class Database {
 41	    private static HikariDataSource dataSource;
 42	
 43	    public static void init(String dbUrl, String dbUser, String dbPassword) {
 44	        HikariConfig config = new HikariConfig();
 45	        config.setJdbcUrl(dbUrl);
 46	        config.setUsername(dbUser);
 47	        config.setPassword(dbPassword);
 48	        config.setMaximumPoolSize(10);
 49	        config.setAutoCommit(true);
 50	
 51	        dataSource = new HikariDataSource(config);
 52	
 53	        createSchema();
 54	    }
 55	
 56	    private static void createSchema() {
 57	        try (Connection conn = dataSource.getConnection();
 58	             Statement stmt = conn.createStatement()) {
 59	
 60	            stmt.execute("""
 61	                CREATE TABLE IF NOT EXISTS rooms (
 62	                    number INT PRIMARY KEY,
 63	                    type VARCHAR(20) NOT NULL,
 64	                    capacity INT NOT NULL,
 65	                    nightly_rate NUMERIC(10, 2) NOT NULL
 66	                )
 67	                """);
 68	
 69	            stmt.execute("""
 70	                CREATE TABLE IF NOT EXISTS reservations (
 71	                    id BIGSERIAL PRIMARY KEY,
 72	                    room_number INT NOT NULL,
 73	                    guest_name VARCHAR(255) NOT NULL,
 74	                    guest_email VARCHAR(255) NOT NULL,
 75	                    guest_cpf VARCHAR(14),
 76	                    company_cnpj VARCHAR(18),
 77	                    company_name VARCHAR(255),
 78	                    guest_passport VARCHAR(20),
 79	                    guest_country VARCHAR(100),
 80	                    check_in DATE NOT NULL,
 81	                    check_out DATE NOT NULL,
 82	                    guests INT NOT NULL,
 83	                    rate_plan VARCHAR(20) NOT NULL,
 84	                    nights INT NOT NULL,
 85	                    subtotal NUMERIC(10, 2) NOT NULL,
 86	                    discount NUMERIC(10, 2) NOT NULL,
 87	                    total NUMERIC(10, 2) NOT NULL,
 88	                    status VARCHAR(20) NOT NULL,
 89	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 90	                    refund NUMERIC(10, 2),
 91	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
 92	                )
 93	                """);
 94	
 95	            stmt.execute("""
 96	                CREATE TABLE IF NOT EXISTS messages (
 97	                    id BIGSERIAL PRIMARY KEY,
 98	                    channel VARCHAR(20) NOT NULL,
 99	                    "to" VARCHAR(255) NOT NULL,
100	                    subject VARCHAR(255) NOT NULL,
101	                    body TEXT NOT NULL
102	                )
103	                """);
104	
105	            insertRoomsIfEmpty();
106	        } catch (Exception e) {
107	            throw new RuntimeException(e);
108	        }
109	    }
110	
111	    private static void insertRoomsIfEmpty() {
112	        try (Connection conn = dataSource.getConnection();
113	             Statement stmt = conn.createStatement()) {
114	
115	            var rs = stmt.executeQuery("SELECT COUNT(*) FROM rooms");
116	            rs.next();
117	            if (rs.getInt(1) == 0) {
118	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90)");
119	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (102, 'STANDARD', 2, 249.90)");
120	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (201, 'DELUXE', 3, 389.90)");
121	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (202, 'DELUXE', 3, 389.90)");
122	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (301, 'SUITE', 4, 579.90)");
123	            }
124	        } catch (Exception e) {
125	            throw new RuntimeException(e);
126	        }
127	    }
128	
129	    public static Connection getConnection() throws java.sql.SQLException {
130	        return dataSource.getConnection();
131	    }
132	}
