145	public class ReservationHandler {
146	    private final ReservationRepository reservationRepository = new ReservationRepository();
147	    private final RoomRepository roomRepository = new RoomRepository();
148	    private final MessageRepository messageRepository = new MessageRepository();
149	    private final ObjectMapper objectMapper = new ObjectMapper();
150	
151	    public void create(Context ctx) {
152	        try {
153	            var body = ctx.bodyAsClass(Map.class);
154	
155	            // Validate identification
156	            String guestCpf = (String) body.get("guestCpf");
157	            String companyCnpj = (String) body.get("companyCnpj");
158	            String companyName = (String) body.get("companyName");
159	            String guestPassport = (String) body.get("guestPassport");
160	            String guestCountry = (String) body.get("guestCountry");
161	
162	            int identificationCount = 0;
163	            if (guestCpf != null) identificationCount++;
164	            if (companyCnpj != null) identificationCount++;
165	            if (guestPassport != null) identificationCount++;
166	
167	            if (identificationCount != 1) {
168	                ctx.status(400).json(new Object() {
169	                    public final String error = "INVALID_REQUEST";
170	                    public final String message = "Must provide exactly one identification method";
171	                });
172	                return;
173	            }
174	
175	            if (companyCnpj != null && companyName == null) {
176	                ctx.status(400).json(new Object() {
177	                    public final String error = "INVALID_REQUEST";
178	                    public final String message = "companyName required when companyCnpj is provided";
179	                });
180	                return;
181	            }
182	
183	            if (guestPassport != null && guestCountry == null) {
184	                ctx.status(400).json(new Object() {
185	                    public final String error = "INVALID_REQUEST";
186	                    public final String message = "guestCountry required when guestPassport is provided";
187	                });
188	                return;
189	            }
190	
191	            // Parse required fields
192	            int roomNumber;
193	            String guestName = (String) body.get("guestName");
194	            String guestEmail = (String) body.get("guestEmail");
195	            LocalDate checkIn;
196	            LocalDate checkOut;
197	            int guests;
198	            String ratePlan = (String) body.get("ratePlan");
199	
200	            try {
201	                roomNumber = ((Number) body.get("roomNumber")).intValue();
202	                checkIn = LocalDate.parse((String) body.get("checkIn"));
203	                checkOut = LocalDate.parse((String) body.get("checkOut"));
204	                guests = ((Number) body.get("guests")).intValue();
205	            } catch (Exception e) {
206	                ctx.status(400).json(new Object() {
207	                    public final String error = "INVALID_REQUEST";
208	                    public final String message = "Invalid input format";
209	                });
210	                return;
211	            }
212	
213	            // Validate room exists
214	            Room room = roomRepository.findByNumber(roomNumber);
215	            if (room == null) {
216	                ctx.status(404).json(new Object() {
217	                    public final String error = "ROOM_NOT_FOUND";
218	                    public final String message = "Room not found";
219	                });
220	                return;
221	            }
222	
223	            // Validate dates
224	            if (!checkOut.isAfter(checkIn)) {
225	                ctx.status(400).json(new Object() {
226	                    public final String error = "INVALID_REQUEST";
227	                    public final String message = "Check-out must be after check-in";
228	                });
229	                return;
230	            }
231	
232	            // Validate guests
233	            if (guests < 1 || guests > room.capacity) {
234	                int statusCode = guests < 1 ? 400 : 422;
235	                String errorCode = guests < 1 ? "INVALID_REQUEST" : "CAPACITY_EXCEEDED";
236	                String finalErrorCode = errorCode;
237	                ctx.status(statusCode).json(new Object() {
238	                    public final String error = finalErrorCode;
239	                    public final String message = "Invalid number of guests";
240	                });
241	                return;
242	            }
243	
244	            // Check room availability
245	            var conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
246	            if (!conflicts.isEmpty()) {
247	                ctx.status(409).json(new Object() {
248	                    public final String error = "ROOM_UNAVAILABLE";
249	                    public final String message = "Room is not available for the selected dates";
250	                });
251	                return;
252	            }
253	
254	            // Calculate prices
255	            int nights = PriceCalculator.calculateNights(checkIn, checkOut);
256	            double subtotal = PriceCalculator.calculateSubtotal(checkIn, checkOut, room.nightlyRate);
257	            double discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
258	            double total = PriceCalculator.round(subtotal - discount);
259	
260	            // Create reservation
261	            Reservation reservation = new Reservation(
262	                    roomNumber, guestName, guestEmail,
263	                    guestCpf, companyCnpj, companyName,
264	                    guestPassport, guestCountry,
265	                    checkIn, checkOut, guests, ratePlan,
266	                    nights, subtotal, discount, total
267	            );
268	
269	            long reservationId = reservationRepository.create(reservation);
270	            reservation.id = reservationId;
271	
272	            ctx.status(201).json(buildReservationResponse(reservation));
273	        } catch (Exception e) {
274	            e.printStackTrace();
275	            ctx.status(500).json(new Object() {
276	                public final String error = "INTERNAL_ERROR";
277	                public final String message = e.getMessage();
278	            });
279	        }
280	    }
281	
282	    public void get(Context ctx) {
283	        try {
284	            long id = Long.parseLong(ctx.pathParam("id"));
285	            Reservation reservation = reservationRepository.findById(id);
286	
287	            if (reservation == null) {
288	                ctx.status(404).json(new Object() {
289	                    public final String error = "RESERVATION_NOT_FOUND";
290	                    public final String message = "Reservation not found";
291	                });
292	                return;
293	            }
294	
295	            ctx.json(buildReservationResponse(reservation));
296	        } catch (Exception e) {
297	            ctx.status(500).json(new Object() {
298	                public final String error = "INTERNAL_ERROR";
299	                public final String message = e.getMessage();
300	            });
301	        }
302	    }
303	
304	    public void confirm(Context ctx) {
305	        try {
306	            long id = Long.parseLong(ctx.pathParam("id"));
307	            Reservation reservation = reservationRepository.findById(id);
308	
309	            if (reservation == null) {
310	                ctx.status(404).json(new Object() {
311	                    public final String error = "RESERVATION_NOT_FOUND";
312	                    public final String message = "Reservation not found";
313	                });
314	                return;
315	            }
316	
317	            if (!"PENDING".equals(reservation.status)) {
318	                ctx.status(409).json(new Object() {
319	                    public final String error = "OPERATION_NOT_ALLOWED";
320	                    public final String message = "Only pending reservations can be confirmed";
321	                });
322	                return;
323	            }
324	
325	            reservation.status = "CONFIRMED";
326	            reservation.amountPaid = reservation.total;
327	            reservationRepository.update(reservation);
328	
329	            // Send confirmation email
330	            sendConfirmationEmail(reservation, id);
331	
332	            ctx.json(buildReservationResponse(reservation));
333	        } catch (Exception e) {
334	            ctx.status(500).json(new Object() {
335	                public final String error = "INTERNAL_ERROR";
336	                public final String message = e.getMessage();
337	            });
338	        }
339	    }
340	
341	    public void cancel(Context ctx) {
342	        try {
343	            long id = Long.parseLong(ctx.pathParam("id"));
344	            Reservation reservation = reservationRepository.findById(id);
345	
346	            if (reservation == null) {
347	                ctx.status(404).json(new Object() {
348	                    public final String error = "RESERVATION_NOT_FOUND";
349	                    public final String message = "Reservation not found";
350	                });
351	                return;
352	            }
353	
354	            if ("CANCELLED".equals(reservation.status) || "CHECKED_OUT".equals(reservation.status)) {
355	                ctx.status(409).json(new Object() {
356	                    public final String error = "OPERATION_NOT_ALLOWED";
357	                    public final String message = "Cannot cancel this reservation";
358	                });
359	                return;
360	            }
361	
362	            if ("CHECKED_IN".equals(reservation.status)) {
363	                ctx.status(409).json(new Object() {
364	                    public final String error = "OPERATION_NOT_ALLOWED";
365	                    public final String message = "Cannot cancel a checked-in reservation";
366	                });
367	                return;
368	            }
369	
370	            String previousStatus = reservation.status;
371	            reservation.status = "CANCELLED";
372	
373	            if ("CONFIRMED".equals(previousStatus) && "STANDARD".equals(reservation.ratePlan)) {
374	                reservation.refund = reservation.amountPaid;
375	            } else {
376	                reservation.refund = 0.0;
377	            }
378	
379	            reservationRepository.update(reservation);
380	
381	            ctx.json(buildReservationResponse(reservation));
382	        } catch (Exception e) {
383	            ctx.status(500).json(new Object() {
384	                public final String error = "INTERNAL_ERROR";
385	                public final String message = e.getMessage();
386	            });
387	        }
388	    }
389	
390	    public void checkIn(Context ctx) {
391	        try {
392	            long id = Long.parseLong(ctx.pathParam("id"));
393	            Reservation reservation = reservationRepository.findById(id);
394	
395	            if (reservation == null) {
396	                ctx.status(404).json(new Object() {
397	                    public final String error = "RESERVATION_NOT_FOUND";
398	                    public final String message = "Reservation not found";
399	                });
400	                return;
401	            }
402	
403	            if (!"CONFIRMED".equals(reservation.status)) {
404	                ctx.status(409).json(new Object() {
405	                    public final String error = "OPERATION_NOT_ALLOWED";
406	                    public final String message = "Only confirmed reservations can check-in";
407	                });
408	                return;
409	            }
410	
411	            reservation.status = "CHECKED_IN";
412	            reservationRepository.update(reservation);
413	
414	            ctx.json(buildReservationResponse(reservation));
415	        } catch (Exception e) {
416	            ctx.status(500).json(new Object() {
417	                public final String error = "INTERNAL_ERROR";
418	                public final String message = e.getMessage();
419	            });
420	        }
421	    }
422	
423	    public void checkOut(Context ctx) {
424	        try {
425	            long id = Long.parseLong(ctx.pathParam("id"));
426	            Reservation reservation = reservationRepository.findById(id);
427	
428	            if (reservation == null) {
429	                ctx.status(404).json(new Object() {
430	                    public final String error = "RESERVATION_NOT_FOUND";
431	                    public final String message = "Reservation not found";
432	                });
433	                return;
434	            }
435	
436	            if (!"CHECKED_IN".equals(reservation.status)) {
437	                ctx.status(409).json(new Object() {
438	                    public final String error = "OPERATION_NOT_ALLOWED";
439	                    public final String message = "Only checked-in reservations can check-out";
440	                });
441	                return;
442	            }
443	
444	            reservation.status = "CHECKED_OUT";
445	            reservationRepository.update(reservation);
446	
447	            Room room = roomRepository.findByNumber(reservation.roomNumber);
448	            Document document = generateDocument(reservation, room, id);
449	
450	            ctx.json(document);
451	        } catch (Exception e) {
452	            ctx.status(500).json(new Object() {
453	                public final String error = "INTERNAL_ERROR";
454	                public final String message = e.getMessage();
455	            });
456	        }
457	    }
458	
459	    public void getDocument(Context ctx) {
460	        try {
461	            long id = Long.parseLong(ctx.pathParam("id"));
462	            Reservation reservation = reservationRepository.findById(id);
463	
464	            if (reservation == null) {
465	                ctx.status(404).json(new Object() {
466	                    public final String error = "RESERVATION_NOT_FOUND";
467	                    public final String message = "Reservation not found";
468	                });
469	                return;
470	            }
471	
472	            if ("PENDING".equals(reservation.status)) {
473	                ctx.status(409).json(new Object() {
474	                    public final String error = "OPERATION_NOT_ALLOWED";
475	                    public final String message = "Document only available for paid reservations";
476	                });
477	                return;
478	            }
479	
480	            Room room = roomRepository.findByNumber(reservation.roomNumber);
481	            Document document = generateDocument(reservation, room, id);
482	
483	            ctx.json(document);
484	        } catch (Exception e) {
485	            ctx.status(500).json(new Object() {
486	                public final String error = "INTERNAL_ERROR";
487	                public final String message = e.getMessage();
488	            });
489	        }
490	    }
491	
492	    private Document generateDocument(Reservation reservation, Room room, long reservationId) {
493	        var generator = DocumentGeneratorFactory.create(reservation);
494	        String text = generator.generate(reservation, room, reservationId);
495	        String title = generator.getTitle();
496	
497	        Document doc = new Document(
498	                reservationId, reservation.guestName, reservation.guestCpf,
499	                reservation.companyCnpj, reservation.companyName,
500	                reservation.guestPassport, reservation.guestCountry,
501	                room.number, room.type,
502	                formatDateForJson(reservation.checkIn),
503	                formatDateForJson(reservation.checkOut),
504	                reservation.nights,
505	                reservation.subtotal, reservation.discount, reservation.total,
506	                text
507	        );
508	        doc.title = title;
509	        return doc;
510	    }
511	
512	    private String formatDateForJson(LocalDate date) {
513	        return date.toString();
514	    }
515	
516	    private void sendConfirmationEmail(Reservation reservation, long reservationId) throws Exception {
517	        Room room = roomRepository.findByNumber(reservation.roomNumber);
518	        var generator = DocumentGeneratorFactory.create(reservation);
519	        String documentText = generator.generate(reservation, room, reservationId);
520	
521	        String emailBody = String.format("""
522	            Olá, %s!
523	
524	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
525	
526	            %s
527	
528	            A entrada é a partir das 14h, e a saída, até as 12h.
529	            Até breve!
530	            """, reservation.guestName, documentText);
531	
532	        Message message = new Message("EMAIL", reservation.guestEmail, "Reserva confirmada - Pousada Maré Alta", emailBody);
533	        messageRepository.save(message);
534	    }
535	
