537	        return new Object() {
538	            public final Long id = reservation.id;
539	            public final int roomNumber = reservation.roomNumber;
540	            public final String guestName = reservation.guestName;
541	            public final String guestEmail = reservation.guestEmail;
542	            public final String guestCpf = reservation.guestCpf;
543	            public final String companyCnpj = reservation.companyCnpj;
544	            public final String companyName = reservation.companyName;
545	            public final String guestPassport = reservation.guestPassport;
546	            public final String guestCountry = reservation.guestCountry;
547	            public final String checkIn = formatDateForJson(reservation.checkIn);
548	            public final String checkOut = formatDateForJson(reservation.checkOut);
549	            public final int guests = reservation.guests;
550	            public final String ratePlan = reservation.ratePlan;
551	            public final int nights = reservation.nights;
552	            public final double subtotal = reservation.subtotal;
553	            public final double discount = reservation.discount;
554	            public final double total = reservation.total;
555	            public final String status = reservation.status;
556	            public final double amountPaid = reservation.amountPaid;
557	            public final Double refund = reservation.refund;
558	        };
559	    }
560	}

