151	    public void create(Context ctx) {
152	        try {
153	            var body = ctx.bodyAsClass(Map.class);
154	
155	            // Validate identification
156	            String guestCpf = (String) body.get("guestCpf");
157	            String companyCnpj = (String) body.get("companyCnpj");
158	            String companyName = (String) body.get("companyName");
159	            String guestPassport = (String) body.get("guestPassport");
160	            String guestCountry = (String) body.get("guestCountry");
161	
162	            int identificationCount = 0;
163	            if (guestCpf != null) identificationCount++;
164	            if (companyCnpj != null) identificationCount++;
165	            if (guestPassport != null) identificationCount++;
166	
167	            if (identificationCount != 1) {
168	                ctx.status(400).json(new Object() {
169	                    public final String error = "INVALID_REQUEST";
170	                    public final String message = "Must provide exactly one identification method";
171	                });
172	                return;
173	            }
174	
175	            if (companyCnpj != null && companyName == null) {
176	                ctx.status(400).json(new Object() {
177	                    public final String error = "INVALID_REQUEST";
178	                    public final String message = "companyName required when companyCnpj is provided";
179	                });
180	                return;
181	            }
182	
183	            if (guestPassport != null && guestCountry == null) {
184	                ctx.status(400).json(new Object() {
185	                    public final String error = "INVALID_REQUEST";
186	                    public final String message = "guestCountry required when guestPassport is provided";
187	                });
188	                return;
189	            }
190	
191	            // Parse required fields
192	            int roomNumber;
193	            String guestName = (String) body.get("guestName");
194	            String guestEmail = (String) body.get("guestEmail");
195	            LocalDate checkIn;
196	            LocalDate checkOut;
197	            int guests;
198	            String ratePlan = (String) body.get("ratePlan");
199	
200	            try {
201	                roomNumber = ((Number) body.get("roomNumber")).intValue();
202	                checkIn = LocalDate.parse((String) body.get("checkIn"));
203	                checkOut = LocalDate.parse((String) body.get("checkOut"));
204	                guests = ((Number) body.get("guests")).intValue();
205	            } catch (Exception e) {
206	                ctx.status(400).json(new Object() {
207	                    public final String error = "INVALID_REQUEST";
208	                    public final String message = "Invalid input format";
209	                });
210	                return;
211	            }
212	
213	            // Validate room exists
214	            Room room = roomRepository.findByNumber(roomNumber);
215	            if (room == null) {
216	                ctx.status(404).json(new Object() {
217	                    public final String error = "ROOM_NOT_FOUND";
218	                    public final String message = "Room not found";
219	                });
220	                return;
221	            }
222	
223	            // Validate dates
224	            if (!checkOut.isAfter(checkIn)) {
225	                ctx.status(400).json(new Object() {
226	                    public final String error = "INVALID_REQUEST";
227	                    public final String message = "Check-out must be after check-in";
228	                });
229	                return;
230	            }
231	
232	            // Validate guests
233	            if (guests < 1 || guests > room.capacity) {
234	                int statusCode = guests < 1 ? 400 : 422;
235	                String errorCode = guests < 1 ? "INVALID_REQUEST" : "CAPACITY_EXCEEDED";
236	                String finalErrorCode = errorCode;
237	                ctx.status(statusCode).json(new Object() {
238	                    public final String error = finalErrorCode;
239	                    public final String message = "Invalid number of guests";
240	                });
241	                return;
242	            }
243	
244	            // Check room availability
245	            var conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
246	            if (!conflicts.isEmpty()) {
247	                ctx.status(409).json(new Object() {
248	                    public final String error = "ROOM_UNAVAILABLE";
249	                    public final String message = "Room is not available for the selected dates";
250	                });
251	                return;
252	            }
253	
254	            // Calculate prices
255	            int nights = PriceCalculator.calculateNights(checkIn, checkOut);
256	            double subtotal = PriceCalculator.calculateSubtotal(checkIn, checkOut, room.nightlyRate);
257	            double discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
258	            double total = PriceCalculator.round(subtotal - discount);
259	
260	            // Create reservation
261	            Reservation reservation = new Reservation(
262	                    roomNumber, guestName, guestEmail,
263	                    guestCpf, companyCnpj, companyName,
264	                    guestPassport, guestCountry,
265	                    checkIn, checkOut, guests, ratePlan,
266	                    nights, subtotal, discount, total
267	            );
268	
269	            long reservationId = reservationRepository.create(reservation);
270	            reservation.id = reservationId;
271	
272	            ctx.status(201).json(buildReservationResponse(reservation));
273	        } catch (Exception e) {
274	            e.printStackTrace();
275	            ctx.status(500).json(new Object() {
276	                public final String error = "INTERNAL_ERROR";
277	                public final String message = e.getMessage();
278	            });
279	        }
280	    }
