317	public class ReportHandler {
318	    private final ReservationRepository reservationRepository = new ReservationRepository();
319	    private final RoomRepository roomRepository = new RoomRepository();
320	
321	    public void occupancy(Context ctx) {
322	        try {
323	            String dateParam = ctx.queryParam("date");
324	            if (dateParam == null) {
325	                ctx.status(400).json(new Object() {
326	                    public final String error = "INVALID_REQUEST";
327	                    public final String message = "date parameter required";
328	                });
329	                return;
330	            }
331	
332	            LocalDate date = LocalDate.parse(dateParam);
333	
334	            StringBuilder csv = new StringBuilder();
335	            csv.append("room,type,reservation,check_in,check_out\n");
336	
337	            var rooms = roomRepository.findAll();
338	            int occupiedCount = 0;
339	
340	            for (var room : rooms) {
341	                var reservations = reservationRepository.findByRoomAndDate(room.number, date);
342	                if (!reservations.isEmpty()) {
343	                    for (var res : reservations) {
344	                        if ("CONFIRMED".equals(res.status) || "CHECKED_IN".equals(res.status) || "CHECKED_OUT".equals(res.status)) {
345	                            csv.append(room.number).append(",")
346	                                    .append(room.type).append(",")
347	                                    .append(res.id).append(",")
348	                                    .append(res.checkIn).append(",")
349	                                    .append(res.checkOut).append("\n");
350	                            occupiedCount++;
351	                        }
352	                    }
353	                }
354	            }
355	
356	            csv.append("total,").append(occupiedCount).append("/").append(rooms.size());
357	
358	            ctx.contentType("text/csv;charset=utf-8").result(csv.toString());
359	        } catch (DateTimeParseException e) {
360	            ctx.status(400).json(new Object() {
361	                public final String error = "INVALID_REQUEST";
362	                public final String message = "Invalid date format";
363	            });
364	        } catch (Exception e) {
365	            ctx.status(500).json(new Object() {
366	                public final String error = "INTERNAL_ERROR";
367	                public final String message = e.getMessage();
368	            });
369	        }
370	    }
371	
372	    public void revenue(Context ctx) {
373	        try {
374	            String monthParam = ctx.queryParam("month");
375	            if (monthParam == null) {
376	                ctx.status(400).json(new Object() {
377	                    public final String error = "INVALID_REQUEST";
378	                    public final String message = "month parameter required";
379	                });
380	                return;
381	            }
382	
383	            var parts = monthParam.split("-");
384	            if (parts.length != 2) {
385	                ctx.status(400).json(new Object() {
386	                    public final String error = "INVALID_REQUEST";
387	                    public final String message = "Invalid month format";
388	                });
389	                return;
390	            }
391	
392	            int year = Integer.parseInt(parts[0]);
393	            int month = Integer.parseInt(parts[1]);
394	
395	            StringBuilder csv = new StringBuilder();
396	            csv.append("reservation,room,check_in,check_out,status,amount\n");
397	
398	            var reservations = reservationRepository.findByMonthWithMoney(year, month);
399	
400	            double totalAmount = 0;
401	
402	            for (var res : reservations) {
403	                double amountForReport = res.amountPaid - (res.refund != null ? res.refund : 0);
404	
405	                csv.append(res.id).append(",")
406	                        .append(res.roomNumber).append(",")
407	                        .append(res.checkIn).append(",")
408	                        .append(res.checkOut).append(",")
409	                        .append(res.status).append(",")
410	                        .append(String.format("%.2f", amountForReport)).append("\n");
411	
412	                totalAmount += amountForReport;
413	            }
414	
415	            csv.append("total,,,,").append(String.format("%.2f", totalAmount));
416	
417	            ctx.contentType("text/csv;charset=utf-8").result(csv.toString());
418	        } catch (NumberFormatException e) {
419	            ctx.status(400).json(new Object() {
420	                public final String error = "INVALID_REQUEST";
