318	package com.pousadamareaalta.utils;
319	
320	import java.math.BigDecimal;
321	import java.math.RoundingMode;
322	import java.time.LocalDate;
323	import java.time.temporal.ChronoUnit;
324	
325	public class PriceCalculator {
326	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
327	
328	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
329	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
330	    }
331	
332	    public static double calculatePricePerNight(LocalDate date, double baseRate) {
333	        if (isHighSeason(date)) {
334	            return round(baseRate * 1.20);
335	        }
336	        return round(baseRate);
337	    }
338	
339	    private static boolean isHighSeason(LocalDate date) {
340	        int month = date.getMonthValue();
341	        int day = date.getDayOfMonth();
342	
343	        if (month == 7) return true;
344	
345	        if (month == 12 && day >= 15) return true;
346	
347	        if (month >= 1 && month <= 2) return true;
348	
349	        return false;
350	    }
351	
352	    public static double calculateSubtotal(LocalDate checkIn, LocalDate checkOut, double baseRate) {
353	        int nights = calculateNights(checkIn, checkOut);
354	        double total = BigDecimal.ZERO.doubleValue();
355	
356	        for (int i = 0; i < nights; i++) {
357	            LocalDate date = checkIn.plusDays(i);
358	            double pricePerNight = calculatePricePerNight(date, baseRate);
359	            total += pricePerNight;
360	        }
361	
362	        return round(total);
363	    }
364	
365	    public static double calculateDiscount(double subtotal, String ratePlan) {
366	        if ("NON_REFUNDABLE".equals(ratePlan)) {
367	            return round(subtotal * 0.15);
368	        }
369	        return 0;
370	    }
371	
372	    public static double round(double value) {
373	        return new BigDecimal(value).setScale(2, ROUNDING_MODE).doubleValue();
374	    }
375	}

